def match_rule(rule, merchant_data, transaction):
    if rule['card_scheme'] != transaction['card_scheme']:
        return False

    if rule['account_type'] and merchant_data['account_type'] not in rule['account_type']:
        return False

    if rule['merchant_category_code'] and merchant_data['merchant_category_code'] not in rule['merchant_category_code']:
        return False

    if rule['is_credit'] is not None and transaction['is_credit'] != rule['is_credit']:
        return False

    if rule['aci'] and transaction['aci'] not in rule['aci']:
        return False

    if rule['intracountry'] is not None:
        is_intra = transaction['issuing_country'] == transaction['acquirer_country']
        if is_intra != bool(rule['intracountry']):
            return False

    # Volume and Fraud level
    # These depend on the merchant's performance in that month
    # We'll handle them later if needed

    # Capture delay
    if rule['capture_delay'] is not None:
        if merchant_data['capture_delay'] != rule['capture_delay']:
            # Handle the mappings like <3, 3-5, >5
            cd = merchant_data['capture_delay']
            rcd = rule['capture_delay']
            if rcd == '<3':
                if cd not in ['1', '2', 'immediate']: return False
            elif rcd == '3-5':
                if cd not in ['3', '4', '5']: return False
            elif rcd == '>5':
                if cd not in ['6', '7', 'manual']: return False # 'manual' might be > 5?
            elif rcd == 'immediate':
                if cd != 'immediate': return False
            elif rcd == 'manual':
                if cd != 'manual': return False
            else:
                if cd != rcd: return False

    return True

