def match_capture_delay(rcd, mcd):
    if not rcd: return True
    if rcd == '<3': return mcd in ['1', '2', 'immediate']
    if rcd == '3-5': return mcd in ['3', '4', '5']
    if rcd == '>5': return mcd in ['6', '7', 'manual']
    if rcd == 'immediate': return mcd == 'immediate'
    if rcd == 'manual': return mcd == 'manual'
    return mcd == rcd

def parse_range(r):
    if not r: return None
    r_clean = r.replace('m', '000000').replace('k', '000')
    is_percent = '%' in r_clean
    r_clean = r_clean.replace('%', '')
    if '>' in r_clean:
        val = float(r_clean.replace('>', ''))
        if is_percent: val /= 100
        return (val, float('inf'))
    if '<' in r_clean:
        val = float(r_clean.replace('<', ''))
        if is_percent: val /= 100
        return (0, val)
    if '-' in r_clean:
        parts = r_clean.split('-')
        low = float(parts[0]); high = float(parts[1])
        if is_percent: low /= 100; high /= 100
        return (low, high)
    return None

def in_range(val, r_str):
    if not r_str: return True
    r = parse_range(r_str)
    if not r: return True
    return r[0] <= val < r[1]

